int handle_flush_notification(const struct km_event *c)
{
    struct sk_buff *skb;
    struct sadb_msg *msg;
    int err;

    skb = alloc_skb(sizeof(*msg), GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    msg = skb_put(skb, sizeof(*msg));
    msg->sadb_msg_type = SADB_MSG_FLUSH;
    msg->sadb_msg_satype = c->proto;
    msg->sadb_msg_len = sizeof(*msg) / sizeof(uint64_t);
    msg->sadb_msg_sequence = c->seq;
    msg->sadb_msg_error = 0;

    err = netlink_broadcast(skb, 0, NETLINK_CRYPTO, GFP_ATOMIC, NULL);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

