#include <linux/skbuff.h>
#include <linux/netlink.h>
#include <linux/err.h>

int handle_sa_flush_notify(const struct km_event *c)
{
    struct sk_buff *skb;
    struct nlmsghdr *nlh;
    int err;

    skb = alloc_skb(NLMSG_GOODSIZE, GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    nlh = nlmsg_put(skb, 0, 0, NLMSG_DONE, 0, 0);
    if (!nlh) {
        kfree_skb(skb);
        return -ENOBUFS;
    }

    nlh->nlmsg_type = c->proto;
    nlh->nlmsg_seq = c->seq;
    nlh->nlmsg_flags = NLM_F_MULTI;

    netlink_broadcast(skb, 0, 0, NLGRP_SAC, GFP_KERNEL);
    return 0;
}
